mapper.select:
SELECT trace_id,
       MIN(tenant_id) AS tenant_id,
       MIN(project_id) AS project_id,
       MIN(key_id) AS key_id,
       MIN(created_at) AS started_at,
       MAX(created_at) AS finished_at,
       COUNT(1) AS event_count,
       MAX(status) AS status
FROM trace_events


        tenant_id = #{tenantId,jdbcType=VARCHAR}


        AND project_id = #{projectId,jdbcType=VARCHAR}


        AND key_id = #{keyId,jdbcType=VARCHAR}


        AND created_at >= #{from,jdbcType=TIMESTAMP}


        AND created_at <= #{to,jdbcType=TIMESTAMP}


GROUP BY trace_id

    HAVING MAX(status) = #{status,jdbcType=INTEGER}

ORDER BY MIN(created_at) DESC, trace_id ASC
LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}
